const $=s=>document.querySelector(s);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let profile=read('notebook-profile',{name:'Abishek Dhakal',intro:'I’m a student at Allegheny College with interests in computer science, economics, humanities, and mathematics. Welcome to my personal website—a place to learn more about me and what I’m working on.'});
let notes=read('notebook-ideas',[]);
let blogs=read('notebook-blogs',[]);
let editingBlog=null;
let literature=read('notebook-literature',[]);
let editingLiterature=null;
const projects=[{title:'A search engine, from scratch',desc:'Exploring how documents become searchable: crawling, indexing, and ranking in a small experimental search engine.',tags:['Python','Information retrieval'],body:'Sample project\n\nUse this space to tell the story behind your project: the problem you wanted to solve, how you approached it, and what you learned. Add a repository or live demo when your project is ready.'},{title:'Seeing algorithms in motion',desc:'An interactive way to understand sorting and graph traversal, one step at a time.',tags:['JavaScript','Algorithms'],body:'Sample project\n\nDescribe the algorithms you explored, the interactions you built, and what the visualizations help people understand.'},{title:'A tiny programming language',desc:'An experiment in language design, from the first token to a working interpreter.',tags:['Compilers','Language design'],body:'Sample project\n\nShare your language’s syntax, the design decisions behind it, and a small example program.'}];
const research=[{title:'How do we make machine learning more interpretable?',desc:'A place for reading notes, open questions, and experiments on understanding model decisions.',tags:['Machine learning','Reading notes'],body:'Sample research entry\n\nAdd the question you are investigating, links to the papers you are reading, and your own observations. Distinguish published findings from your hypotheses.'},{title:'The trade-offs behind distributed systems',desc:'Thinking through consistency, fault tolerance, and the choices that shape reliable systems.',tags:['Distributed systems','Exploration'],body:'Sample research entry\n\nDocument the systems you are studying, the trade-offs you have noticed, and questions worth investigating next.'}];
function heading(label,title,desc){return `<div class="page-lead"><div class="eyebrow">${label}</div><h1>${title}</h1><p class="intro">${desc}</p></div>`}
function entries(data,type){return `<div class="list">${data.map((x,i)=>`<button class="entry" data-detail="${type}:${i}"><span class="meta">${type==='notes'?'PERSONAL DRAFT':'SAMPLE '+(type==='projects'?'PROJECT':'RESEARCH ENTRY')}</span><h2>${escapeHTML(x.title)}</h2><p>${escapeHTML(x.desc??x.body.slice(0,180))}</p>${(x.tags??[]).map(t=>`<span class="tag">${escapeHTML(t)}</span>`).join('')}${type==='notes'?'<span class="meta">Open draft</span>':''}</button>`).join('')}</div>`}
function render(){const page=['about','projects','research','blogs','literature','ideas'].includes(location.hash.slice(1))?location.hash.slice(1):'about';document.querySelectorAll('nav a').forEach(a=>{const active=a.dataset.page===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
if(page==='about')$('#content').innerHTML=`<section class="hero"><div><div class="eyebrow">HELLO, WORLD.</div><h1>I’m <em>${escapeHTML(profile.name)}.</em><br>Curious by nature.<br>A builder at heart.</h1><p class="intro">${escapeHTML(profile.intro)}</p><div class="actions"><a class="button primary" href="#projects">Explore my projects</a><button class="button" id="edit-profile">Edit introduction</button></div><div class="skills"><span class="tag">Computer science</span><span class="tag">Economics</span><span class="tag">Humanities</span><span class="tag">Mathematics</span></div></div><div class="identity" aria-hidden="true"><strong>{ me }</strong><span>STILL EXPLORING</span></div></section><div class="divider"></div><section><div class="section-heading"><h2>A few things I’m working on</h2><span class="meta">BUILD · EXPLORE · REFLECT</span></div><div class="cards"><a class="card" href="#projects"><div class="card-icon">⌘</div><h3>Things I build</h3><p>Experiments, side projects, and ideas turned into code.</p><div class="card-foot"><span>Explore projects</span><span class="count">01</span></div></a><a class="card" href="#research"><div class="card-icon">▧</div><h3>Questions I explore</h3><p>Research interests, reading notes, and deeper investigations.</p><div class="card-foot"><span>Browse research</span><span class="count">02</span></div></a><a class="card" href="#blogs"><div class="card-icon">▤</div><h3>What I’m learning</h3><p>Project stories, lessons learned, and discoveries from building.</p><div class="card-foot"><span>Read the blog</span><span class="count">03</span></div></a><a class="card literature-card" href="#literature"><div class="card-icon">¶</div><h3>Words beyond the work</h3><p>Essays, poems, and reflections on the world and our place in it.</p><div class="card-foot"><span>Explore literature</span><span class="count">04</span></div></a><a class="card" href="#ideas"><div class="card-icon">✳</div><h3>Thoughts along the way</h3><p>A notebook for small discoveries and ideas worth keeping.</p><div class="card-foot"><span>Read the notebook</span><span class="count">05</span></div></a></div></section><div class="note-strip"><span>✳</span><p><strong>Good ideas start with a little curiosity.</strong><br>This space grows with the things I learn and make.</p></div>`;
if(page==='projects')$('#content').innerHTML=heading('BUILDING & EXPERIMENTING','Projects<span style="color:var(--blue)">.</span>','A collection of things built to learn, explore, and solve problems.')+entries(projects,'projects');
if(page==='research')$('#content').innerHTML=heading('QUESTIONS WORTH ASKING','Research<span style="color:var(--blue)">.</span>','A space for investigations, paper notes, and questions that keep me thinking.')+entries(research,'research');
if(page==='ideas')$('#content').innerHTML=heading('THE OPEN NOTEBOOK','Ideas & notes<span style="color:var(--blue)">.</span>','Small observations. Unfinished thoughts. The beginnings of something new.')+`<form class="editor" id="idea-form"><label for="idea-title">Give your idea a title</label><input id="idea-title" name="title" placeholder="What’s on your mind?" required maxlength="150"><label for="idea-body">Your thoughts</label><textarea id="idea-body" name="body" placeholder="Start writing. It doesn’t need to be finished." required></textarea><p class="hint">Drafts stay in this browser on this device. They are not published or synced.</p><button class="button primary" type="submit">Save draft</button><span class="notice" role="status" id="saved"></span></form><div class="section-heading"><h2>Your notebook</h2><span class="meta">${notes.length} ${notes.length===1?'DRAFT':'DRAFTS'}</span></div>`+(notes.length?entries(notes,'notes'):'<div class="empty">Your notebook is ready for its first idea.</div>');
if(page==='blogs')renderBlogs();
if(page==='literature')renderLiterature();
$('#edit-profile')?.addEventListener('click',editProfile);$('#idea-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const title=f.get('title').trim(),body=f.get('body').trim();if(!title||!body)return;const updated=[{title,body},...notes];try{localStorage.setItem('notebook-ideas',JSON.stringify(updated));notes=updated;render();$('#saved').textContent='Draft saved.'}catch{$('#saved').textContent='Could not save. Please keep a copy of your text.'}});
document.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>{const [type,index]=b.dataset.detail.split(':');const x=({projects,research,notes})[type][index];$('#detail-body').innerHTML=`<div class="eyebrow">${type==='notes'?'YOUR NOTEBOOK':'WORK & EXPLORATION'}</div><h2>${escapeHTML(x.title)}</h2><p>${escapeHTML(x.body)}</p>`;$('#detail').showModal()}));document.title=page==='about'?'Abishek Dhakal — About me':`${page==='ideas'?'Ideas & notes':page[0].toUpperCase()+page.slice(1)} — Personal notebook`;}
function renderBlogs(){
const draft=editingBlog===null?null:blogs[editingBlog];
$('#content').innerHTML=heading('LEARNING BY BUILDING','Blogs<span style="color:var(--blue)">.</span>','Stories from my projects: what I tried, what challenged me, and what I learned.')+`<form class="editor" id="blog-form"><h2>${draft?'Edit your post':'Write a learning post'}</h2><label for="blog-title">Post title</label><input id="blog-title" name="title" value="${escapeHTML(draft?.title??'')}" placeholder="What building this project taught me" required maxlength="150"><label for="blog-project">Related project (optional)</label><input id="blog-project" name="project" value="${escapeHTML(draft?.project??'')}" placeholder="Name of the project" maxlength="150"><label for="blog-body">Your learning story</label><textarea id="blog-body" class="blog-body" name="body" placeholder="What did you build? What did you learn? What would you do differently next time?" required>${escapeHTML(draft?.body??'')}</textarea><p class="hint">Posts are saved as drafts in this browser on this device. They are not published or synced.</p><div class="actions"><button class="button primary" type="submit">${draft?'Save changes':'Save post draft'}</button>${draft?'<button class="button" type="button" id="cancel-blog">Cancel editing</button>':''}<span class="notice" role="status" id="blog-status"></span></div></form><div class="section-heading"><h2>Project learning journal</h2><span class="meta">${blogs.length} ${blogs.length===1?'POST':'POSTS'}</span></div>`+(blogs.length?`<div class="list">${blogs.map((post,i)=>`<article class="entry blog-entry"><div class="meta">LOCAL DRAFT · ${escapeHTML(new Date(post.updatedAt).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}))}</div><h2>${escapeHTML(post.title)}</h2>${post.project?`<span class="tag">Project: ${escapeHTML(post.project)}</span>`:''}<p>${escapeHTML(post.body.slice(0,220))}${post.body.length>220?'…':''}</p><div class="actions"><button class="button" data-read-blog="${i}">Read post</button><button class="button" data-edit-blog="${i}">Edit post</button></div></article>`).join('')}</div>`:'<div class="empty">No posts yet. Start with a lesson from a project you’re working on.</div>');
$('#blog-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const title=f.get('title').trim(),body=f.get('body').trim(),project=f.get('project').trim();if(!title||!body){$('#blog-status').textContent='Add a title and your learning story.';return}const post={title,body,project,updatedAt:new Date().toISOString()},updated=[...blogs];if(editingBlog===null)updated.unshift(post);else updated[editingBlog]=post;try{localStorage.setItem('notebook-blogs',JSON.stringify(updated));blogs=updated;editingBlog=null;renderBlogs();$('#blog-status').textContent='Post draft saved.'}catch{$('#blog-status').textContent='Could not save. Please keep a copy of your text.'}});
$('#cancel-blog')?.addEventListener('click',()=>{editingBlog=null;renderBlogs()});
document.querySelectorAll('[data-read-blog]').forEach(b=>b.addEventListener('click',()=>{const post=blogs[Number(b.dataset.readBlog)];$('#detail-body').innerHTML=`<div class="eyebrow">PROJECT LEARNING · LOCAL DRAFT</div><h2>${escapeHTML(post.title)}</h2>${post.project?`<span class="tag">Project: ${escapeHTML(post.project)}</span>`:''}<p>${escapeHTML(post.body)}</p>`;$('#detail').showModal()}));
document.querySelectorAll('[data-edit-blog]').forEach(b=>b.addEventListener('click',()=>{editingBlog=Number(b.dataset.editBlog);renderBlogs();$('#blog-title').focus();$('#blog-form').scrollIntoView({block:'start'})}));
}

function renderLiterature(){
const draft=editingLiterature===null?null:literature[editingLiterature];
$('#content').innerHTML=heading('WORDS & PERSPECTIVES','Literature<span style="color:var(--blue)">.</span>','Philosophy, politics, religion, poetry, and everything in between. A space to question, reflect, and write freely.')+`<form class="editor literature-editor" id="literature-form"><h2>${draft?'Edit your piece':'Write something of your own'}</h2><label for="literature-title">Title</label><input id="literature-title" name="title" value="${escapeHTML(draft?.title??'')}" placeholder="A question, a feeling, a perspective…" required maxlength="150"><label for="literature-topic">Topic or form (optional)</label><input id="literature-topic" name="topic" list="literature-topics" value="${escapeHTML(draft?.topic??'')}" placeholder="Choose a suggestion or write any topic" maxlength="100"><datalist id="literature-topics"><option value="Philosophy"><option value="Politics"><option value="Religion"><option value="Poetry"><option value="World affairs"><option value="Personal reflection"><option value="Fiction"></datalist><label for="literature-body">Your writing</label><textarea id="literature-body" class="literature-body" name="body" placeholder="An opinion, an essay, a poem, or something that doesn’t fit a category. Start here." required>${escapeHTML(draft?.body??'')}</textarea><p class="hint">Line breaks and spacing are preserved, including in poems. Drafts stay in this browser on this device; they are not published or synced.</p><div class="actions"><button class="button primary" type="submit">${draft?'Save changes':'Save piece'}</button>${draft?'<button class="button" type="button" id="cancel-literature">Cancel editing</button>':''}<span class="notice" role="status" id="literature-status"></span></div></form><div class="section-heading"><h2>Collected writing</h2><span class="meta">${literature.length} ${literature.length===1?'PIECE':'PIECES'}</span></div>`+(literature.length?`<div class="list">${literature.map((piece,i)=>`<article class="entry literature-entry"><div class="meta">LOCAL DRAFT · ${escapeHTML(new Date(piece.updatedAt).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}))}</div><h2>${escapeHTML(piece.title)}</h2>${piece.topic?`<span class="tag">${escapeHTML(piece.topic)}</span>`:''}<p>${escapeHTML(piece.body.slice(0,240))}${piece.body.length>240?'…':''}</p><div class="actions"><button class="button" data-read-literature="${i}">Read piece</button><button class="button" data-edit-literature="${i}">Edit piece</button></div></article>`).join('')}</div>`:'<div class="empty">Your collection is waiting for its first piece. Begin with a thought you keep returning to, or a poem you want to put into words.</div>');
$('#literature-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const title=f.get('title').trim(),topic=f.get('topic').trim(),body=f.get('body');if(!title||!body.trim()){$('#literature-status').textContent='Add a title and some writing.';return}const piece={title,topic,body,updatedAt:new Date().toISOString()},updated=[...literature];if(editingLiterature===null)updated.unshift(piece);else updated[editingLiterature]=piece;try{localStorage.setItem('notebook-literature',JSON.stringify(updated));literature=updated;editingLiterature=null;renderLiterature();$('#literature-status').textContent='Piece saved.'}catch{$('#literature-status').textContent='Could not save. Please keep a copy of your writing.'}});
$('#cancel-literature')?.addEventListener('click',()=>{editingLiterature=null;renderLiterature()});
document.querySelectorAll('[data-read-literature]').forEach(b=>b.addEventListener('click',()=>{const piece=literature[Number(b.dataset.readLiterature)];$('#detail-body').innerHTML=`<div class="eyebrow">LITERATURE · LOCAL DRAFT</div><h2>${escapeHTML(piece.title)}</h2>${piece.topic?`<span class="tag">${escapeHTML(piece.topic)}</span>`:''}<p class="literature-reading">${escapeHTML(piece.body)}</p>`;$('#detail').showModal()}));
document.querySelectorAll('[data-edit-literature]').forEach(b=>b.addEventListener('click',()=>{editingLiterature=Number(b.dataset.editLiterature);renderLiterature();$('#literature-title').focus();$('#literature-form').scrollIntoView({block:'start'})}));
}

function editProfile(){$('#detail-body').innerHTML=`<h2>Your introduction</h2><form class="editor" id="profile-form"><label for="profile-name">Your name</label><input id="profile-name" name="name" value="${escapeHTML(profile.name)}" maxlength="60" required><label for="profile-intro">A little about you</label><textarea id="profile-intro" name="intro" required>${escapeHTML(profile.intro)}</textarea><p class="hint">These edits are saved in this browser only. Send your details in the chat to update the published site for everyone.</p><button class="button primary">Save introduction</button><p role="status" id="profile-status"></p></form>`;$('#detail').showModal();$('#profile-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const next={name:f.get('name').trim(),intro:f.get('intro').trim()};if(!next.name||!next.intro)return;try{localStorage.setItem('notebook-profile',JSON.stringify(next));profile=next;$('#detail').close();render()}catch{$('#profile-status').textContent='Could not save. Please keep a copy of your introduction.'}})}
$('.close').addEventListener('click',()=>$('#detail').close());$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'save_idea_draft',title:'Save an idea draft',description:'Save an idea in this browser only and show the notebook. Does not publish or sync.',inputSchema:{type:'object',properties:{title:{type:'string',maxLength:150},body:{type:'string'}},required:['title','body'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.title!=='string'||typeof input.body!=='string'||!input.title.trim()||!input.body.trim()||input.title.length>150)throw new Error('A title of up to 150 characters and a nonempty body are required.');const updated=[{title:input.title.trim(),body:input.body.trim()},...notes];localStorage.setItem('notebook-ideas',JSON.stringify(updated));notes=updated;location.hash='ideas';render();return {saved:true,storage:'this browser only',draftCount:notes.length}}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
